import {
    readFileSync,
    writeFileSync
} from 'node:fs';

import {
    resolve
} from 'node:path';


// ============================================================
// SETTINGS
// ============================================================

const replayName =
    process.argv[2] ?? 'test';


const XY_RADIUS =
    500;


const MAX_Z_DIFFERENCE =
    128;


// State transitions generated by Script 08 are precise enough
// that members of the same camp should respawn essentially
// simultaneously. Give ourselves a little tolerance.

const RESPAWN_SYNC_TOLERANCE =
    0.20;


const geometryPath =
    resolve(
        'output',
        replayName,
        'neutral_camp_geometry.json'
    );


const transitionsPath =
    resolve(
        'output',
        replayName,
        'resource_state_transitions.jsonl'
    );


const outputPath =
    resolve(
        'output',
        replayName,
        'neutral_camp_membership_diagnostic.json'
    );


// ============================================================
// LOAD
// ============================================================

const geometry =
    JSON.parse(
        readFileSync(
            geometryPath,
            'utf8'
        )
    );


const transitionRows =
    readJsonl(
        transitionsPath
    )
    .filter(
        row =>
            row.className ===
            'CNPC_TrooperNeutral'
    );


console.log('');
console.log(
    `Neutral geometry slots: ${geometry.slots.length}`
);

console.log(
    `Neutral state transitions: ${transitionRows.length}`
);


// ============================================================
// CLASSIFY SPAWN TIER
// ============================================================

const slots =
    geometry.slots.map(
        slot => ({

            ...slot,

            spawnTier:
                classifySpawnTier(
                    slot
                )
        })
    );


// ============================================================
// GEOMETRIC CANDIDATE GROUPS
//
// Crucially:
//
// 1. units must belong to the same spawn-time tier
// 2. XY must be close
// 3. Z must also be close
//
// This prevents vertically stacked camps from being merged.
// ============================================================

const candidateGroups =
    [];


for (
    const tier
    of [
        'TIER_2_MIN',
        'TIER_5_MIN',
        'TIER_8_MIN'
    ]
) {

    const tierSlots =
        slots.filter(
            slot =>
                slot.spawnTier ===
                tier
        );


    const components =
        connectedComponents(
            tierSlots,
            XY_RADIUS,
            MAX_Z_DIFFERENCE
        );


    components
        .sort(
            (
                a,
                b
            ) => {

                const ca =
                    centroid(
                        a
                    );

                const cb =
                    centroid(
                        b
                    );


                return (
                    ca.x -
                    cb.x
                    ||
                    ca.y -
                    cb.y
                );
            }
        );


    for (
        let i = 0;
        i < components.length;
        i++
    ) {

        const prefix =

            tier ===
            'TIER_2_MIN'

                ? 'S'

                : tier ===
                  'TIER_5_MIN'

                    ? 'M'

                    : 'L8';


        candidateGroups.push({

            candidateGroupId:
                `${prefix}${String(i + 1).padStart(2, '0')}`,

            spawnTier:
                tier,

            members:
                components[i],

            centroid:
                centroid(
                    components[i]
                )
        });
    }
}


// ============================================================
// TRANSITIONS BY ENTITY
// ============================================================

const transitionsByEntity =
    new Map();


for (
    const row
    of transitionRows
) {

    const entityIndex =
        Number(
            row.entityIndex
        );


    if (
        !transitionsByEntity.has(
            entityIndex
        )
    ) {

        transitionsByEntity.set(
            entityIndex,
            []
        );
    }


    transitionsByEntity
        .get(
            entityIndex
        )
        .push(
            row
        );
}


// ============================================================
// ANALYZE EACH GEOMETRIC GROUP
// ============================================================

const diagnostics =
    candidateGroups.map(
        analyzeCandidateGroup
    );


// ============================================================
// SUMMARY
// ============================================================

const tierSummary =
    {};


for (
    const tier
    of [
        'TIER_2_MIN',
        'TIER_5_MIN',
        'TIER_8_MIN'
    ]
) {

    const groups =
        diagnostics.filter(
            group =>
                group.spawnTier ===
                tier
        );


    tierSummary[tier] = {

        groupCount:
            groups.length,

        memberCount:
            groups.reduce(
                (
                    sum,
                    group
                ) =>
                    sum +
                    group.memberCount,
                0
            ),

        sizeDistribution:
            countValues(
                groups.map(
                    group =>
                        group.memberCount
                )
            ),

        groupsWithFullSynchronizedRespawn:
            groups.filter(
                group =>
                    group
                        .fullSynchronizedRespawnCount
                    >
                    0
            ).length
    };
}


// ============================================================
// OUTPUT
// ============================================================

const output = {

    replay:
        replayName,

    method:
        'spawn tier + XY/Z geometry + synchronized UP transitions',

    parameters: {

        xyRadius:
            XY_RADIUS,

        maxZDifference:
            MAX_Z_DIFFERENCE,

        respawnSyncToleranceSeconds:
            RESPAWN_SYNC_TOLERANCE
    },

    tierSummary,

    candidateGroups:
        diagnostics,

    interpretation: [
        'Synchronized UP transitions provide strong evidence that entities belong to the same respawn unit/camp.',
        'A geometric blob containing stable smaller respawn cohorts is evidence that multiple camps were merged spatially.',
        'Absence of synchronized respawns is not evidence of separate camps if the relevant camp was never fully cleared during this replay.'
    ]
};


writeFileSync(

    outputPath,

    JSON.stringify(
        output,
        null,
        2
    ),

    'utf8'
);


// ============================================================
// CONSOLE
// ============================================================

console.log('');
console.log(
    '===================================='
);
console.log(
    'NEUTRAL CAMP MEMBERSHIP'
);
console.log(
    '===================================='
);
console.log('');


for (
    const [
        tier,
        summary
    ]
    of Object.entries(
        tierSummary
    )
) {

    console.log(
        `${tier}:`
    );

    console.log(
        `  groups: ${summary.groupCount}`
    );

    console.log(
        `  units: ${summary.memberCount}`
    );

    console.log(
        `  sizes: ${JSON.stringify(summary.sizeDistribution)}`
    );

    console.log(
        `  groups with full synchronized respawn: ${summary.groupsWithFullSynchronizedRespawn}`
    );

    console.log('');
}


// ============================================================
// PRINT AMBIGUOUS GROUPS
// ============================================================

console.log(
    'LARGER / AMBIGUOUS GEOMETRIC GROUPS'
);

console.log(
    '------------------------------------'
);


for (
    const group
    of diagnostics
) {

    if (
        group.memberCount <=
        3
    ) {

        continue;
    }


    console.log('');

    console.log(
        `${group.candidateGroupId}` +
        ` ${group.spawnTier}` +
        ` size=${group.memberCount}`
    );


    console.log(
        `  members: ${group.entityIndexes.join(', ')}`
    );


    console.log(
        `  composition: ${JSON.stringify(group.unitTypeCounts)}`
    );


    console.log(
        `  full synchronized respawns: ${group.fullSynchronizedRespawnCount}`
    );


    console.log(
        `  observed respawn cohort patterns:`
    );


    for (
        const pattern
        of group.respawnCohortPatterns
    ) {

        console.log(
            `    [${pattern.members.join(', ')}] x${pattern.count}`
        );
    }
}


console.log('');
console.log(
    `Output:\n${outputPath}`
);
console.log('');


// ============================================================
// GROUP ANALYSIS
// ============================================================

function analyzeCandidateGroup(
    group
) {

    const entityIndexes =
        group.members.map(
            member =>
                member.entityIndex
        );


    const allUpEvents =
        [];


    const memberDiagnostics =
        group.members.map(
            member => {

                const events =
                    transitionsByEntity
                        .get(
                            member.entityIndex
                        )
                    ??
                    [];


                const downs =
                    events.filter(
                        event =>
                            String(
                                event.transition
                            )
                            .toUpperCase()
                            ===
                            'DOWN'
                    );


                const ups =
                    events.filter(
                        event =>
                            String(
                                event.transition
                            )
                            .toUpperCase()
                            ===
                            'UP'
                    );


                for (
                    const event
                    of ups
                ) {

                    const time =
                        Number(
                            event.matchTimeSeconds
                        );


                    if (
                        Number.isFinite(
                            time
                        )
                    ) {

                        allUpEvents.push({

                            entityIndex:
                                member.entityIndex,

                            time,

                            downtimeSeconds:
                                finiteOrNull(
                                    event.downtimeSeconds
                                )
                        });
                    }
                }


                return {

                    entityIndex:
                        member.entityIndex,

                    unitType:
                        member.unitType,

                    position:
                        member.position,

                    downCount:
                        downs.length,

                    upCount:
                        ups.length,

                    downTimes:
                        downs
                            .map(
                                event =>
                                    finiteOrNull(
                                        event.matchTimeSeconds
                                    )
                            )
                            .filter(
                                Number.isFinite
                            ),

                    upTimes:
                        ups
                            .map(
                                event =>
                                    finiteOrNull(
                                        event.matchTimeSeconds
                                    )
                            )
                            .filter(
                                Number.isFinite
                            )
                };
            }
        );


    // ========================================================
    // GROUP UP EVENTS INTO TIME COHORTS
    // ========================================================

    const respawnCohorts =
        clusterRespawns(
            allUpEvents,
            RESPAWN_SYNC_TOLERANCE
        );


    // Remove accidental duplicate entity IDs inside one cohort.

    for (
        const cohort
        of respawnCohorts
    ) {

        cohort.members =
            [...new Set(
                cohort.members
            )]
            .sort(
                (
                    a,
                    b
                ) =>
                    a - b
            );


        cohort.memberCount =
            cohort.members.length;
    }


    const fullSynchronizedRespawns =
        respawnCohorts.filter(
            cohort =>
                cohort.memberCount ===
                group.members.length
        );


    // ========================================================
    // RECURRING COHORT PATTERNS
    // ========================================================

    const patternMap =
        new Map();


    for (
        const cohort
        of respawnCohorts
    ) {

        const key =
            cohort.members.join(
                ','
            );


        if (
            !patternMap.has(
                key
            )
        ) {

            patternMap.set(
                key,
                {

                    members:
                        cohort.members,

                    count:
                        0,

                    times:
                        []
                }
            );
        }


        const pattern =
            patternMap.get(
                key
            );


        pattern.count++;

        pattern.times.push(
            cohort.timeSeconds
        );
    }


    const respawnCohortPatterns =
        [...patternMap.values()]
            .sort(
                (
                    a,
                    b
                ) =>
                    b.count -
                    a.count
                    ||
                    b.members.length -
                    a.members.length
            );


    // ========================================================
    // PAIRWISE RESPAWN SYNCHRONY
    // ========================================================

    const pairwiseSynchrony =
        [];


    for (
        let i = 0;
        i < memberDiagnostics.length;
        i++
    ) {

        for (
            let j = i + 1;
            j < memberDiagnostics.length;
            j++
        ) {

            const a =
                memberDiagnostics[i];

            const b =
                memberDiagnostics[j];


            const shared =
                countSynchronizedTimes(
                    a.upTimes,
                    b.upTimes,
                    RESPAWN_SYNC_TOLERANCE
                );


            const denominator =
                Math.min(
                    a.upTimes.length,
                    b.upTimes.length
                );


            pairwiseSynchrony.push({

                entityA:
                    a.entityIndex,

                entityB:
                    b.entityIndex,

                synchronizedRespawns:
                    shared,

                comparableRespawns:
                    denominator,

                synchronyRate:
                    denominator > 0
                        ? shared /
                          denominator
                        : null
            });
        }
    }


    return {

        candidateGroupId:
            group.candidateGroupId,

        spawnTier:
            group.spawnTier,

        memberCount:
            group.members.length,

        entityIndexes,

        centroid:
            group.centroid,

        unitTypeCounts:
            countValues(
                group.members.map(
                    member =>
                        member.unitType
                )
            ),

        members:
            memberDiagnostics,

        respawnCohorts,

        fullSynchronizedRespawnCount:
            fullSynchronizedRespawns.length,

        fullSynchronizedRespawns,

        respawnCohortPatterns,

        pairwiseSynchrony
    };
}


// ============================================================
// SPAWN TIER
// ============================================================

function classifySpawnTier(
    slot
) {

    const tick =
        Number(
            slot.firstObservedTick
        );


    if (
        !Number.isFinite(
            tick
        )
    ) {

        return 'UNKNOWN';
    }


    // These are the three exact first-observation cohorts
    // found by Script 17 in this replay.

    if (
        Math.abs(
            tick -
            9616
        )
        <=
        32
    ) {

        return 'TIER_2_MIN';
    }


    if (
        Math.abs(
            tick -
            21136
        )
        <=
        32
    ) {

        return 'TIER_5_MIN';
    }


    if (
        Math.abs(
            tick -
            32656
        )
        <=
        32
    ) {

        return 'TIER_8_MIN';
    }


    return 'UNKNOWN';
}


// ============================================================
// CONNECTED COMPONENTS
// ============================================================

function connectedComponents(
    slots,
    xyRadius,
    maxZDifference
) {

    const remaining =
        new Map(
            slots.map(
                slot => [
                    slot.entityIndex,
                    slot
                ]
            )
        );


    const components =
        [];


    while (
        remaining.size
    ) {

        const [
            firstIndex,
            first
        ] =
            remaining
                .entries()
                .next()
                .value;


        remaining.delete(
            firstIndex
        );


        const queue =
            [first];


        const component =
            [];


        while (
            queue.length
        ) {

            const current =
                queue.shift();


            component.push(
                current
            );


            for (
                const [
                    otherIndex,
                    other
                ]
                of [...remaining]
            ) {

                const xy =
                    distanceXY(
                        current.position,
                        other.position
                    );


                const dz =
                    Math.abs(
                        current.position.z -
                        other.position.z
                    );


                if (
                    xy <=
                    xyRadius
                    &&
                    dz <=
                    maxZDifference
                ) {

                    remaining.delete(
                        otherIndex
                    );


                    queue.push(
                        other
                    );
                }
            }
        }


        components.push(
            component
        );
    }


    return components;
}


// ============================================================
// RESPAWN COHORTS
// ============================================================

function clusterRespawns(
    events,
    tolerance
) {

    const sorted =
        [...events]
            .sort(
                (
                    a,
                    b
                ) =>
                    a.time -
                    b.time
            );


    const cohorts =
        [];


    for (
        const event
        of sorted
    ) {

        const last =
            cohorts.at(
                -1
            );


        if (
            !last
            ||
            event.time -
            last.lastTime
            >
            tolerance
        ) {

            cohorts.push({

                timeSeconds:
                    event.time,

                firstTime:
                    event.time,

                lastTime:
                    event.time,

                members:
                    [
                        event.entityIndex
                    ]
            });

        } else {

            last.members.push(
                event.entityIndex
            );


            last.lastTime =
                event.time;


            last.timeSeconds =
                (
                    last.firstTime +
                    last.lastTime
                )
                /
                2;
        }
    }


    return cohorts;
}


// ============================================================
// PAIRWISE SYNCHRONY
// ============================================================

function countSynchronizedTimes(
    a,
    b,
    tolerance
) {

    let count =
        0;


    const usedB =
        new Set();


    for (
        const timeA
        of a
    ) {

        let bestIndex =
            null;

        let bestDelta =
            Infinity;


        for (
            let i = 0;
            i < b.length;
            i++
        ) {

            if (
                usedB.has(
                    i
                )
            ) {

                continue;
            }


            const delta =
                Math.abs(
                    timeA -
                    b[i]
                );


            if (
                delta <
                bestDelta
            ) {

                bestDelta =
                    delta;

                bestIndex =
                    i;
            }
        }


        if (
            bestIndex !==
            null
            &&
            bestDelta <=
            tolerance
        ) {

            usedB.add(
                bestIndex
            );

            count++;
        }
    }


    return count;
}


// ============================================================
// GEOMETRY
// ============================================================

function distanceXY(
    a,
    b
) {

    return Math.hypot(

        a.x - b.x,

        a.y - b.y
    );
}


function centroid(
    members
) {

    return {

        x:
            average(
                members.map(
                    member =>
                        member.position.x
                )
            ),

        y:
            average(
                members.map(
                    member =>
                        member.position.y
                )
            ),

        z:
            average(
                members.map(
                    member =>
                        member.position.z
                )
            )
    };
}


// ============================================================
// HELPERS
// ============================================================

function countValues(
    values
) {

    const result =
        {};


    for (
        const value
        of values
    ) {

        const key =
            String(
                value
            );


        result[key] =
            (
                result[key]
                ??
                0
            )
            +
            1;
    }


    return result;
}


function finiteOrNull(
    value
) {

    const number =
        Number(
            value
        );


    return Number.isFinite(
        number
    )
        ? number
        : null;
}


function average(
    values
) {

    if (
        !values.length
    ) {

        return null;
    }


    return values.reduce(
        (
            sum,
            value
        ) =>
            sum +
            value,
        0
    )
    /
    values.length;
}


function readJsonl(
    path
) {

    return readFileSync(
        path,
        'utf8'
    )
        .split(
            /\r?\n/
        )
        .filter(
            Boolean
        )
        .map(
            line =>
                JSON.parse(
                    line
                )
        );
}